import { readFile } from 'node:fs/promises';

/**
 * @typedef {Object} ComparisonMetric
 * @property {string} name Human-readable metric name.
 * @property {number|null} baseline Baseline measurement.
 * @property {number|null} optimized Optimized measurement.
 * @property {number|null} changePercent Relative change where a positive latency value is an improvement.
 */

/**
 * Loads a compact summary generated by provider-load.js.
 *
 * @param {string} path Summary JSON path.
 * @returns {Promise<Object>} Parsed summary.
 */
async function loadSummary(path) {
    return JSON.parse(await readFile(path, 'utf8'));
}

/**
 * Calculates improvement for metrics where lower values are better.
 *
 * @param {number|null} baseline Baseline value.
 * @param {number|null} optimized Optimized value.
 * @returns {number|null} Improvement percentage or null for unavailable values.
 */
function lowerIsBetter(baseline, optimized) {
    if (typeof baseline !== 'number' || typeof optimized !== 'number' || baseline === 0) return null;
    return ((baseline - optimized) / baseline) * 100;
}

/**
 * Calculates improvement for metrics where higher values are better.
 *
 * @param {number|null} baseline Baseline value.
 * @param {number|null} optimized Optimized value.
 * @returns {number|null} Improvement percentage or null for unavailable values.
 */
function higherIsBetter(baseline, optimized) {
    if (typeof baseline !== 'number' || typeof optimized !== 'number' || baseline === 0) return null;
    return ((optimized - baseline) / baseline) * 100;
}

/**
 * Formats a nullable measurement for a console table.
 *
 * @param {number|null} value Measurement value.
 * @param {number} digits Decimal digits to display.
 * @returns {string} Display value.
 */
function format(value, digits = 2) {
    return typeof value === 'number' ? value.toFixed(digits) : 'n/a';
}

/**
 * Builds the comparison rows shown to the developer.
 *
 * @param {Object} baseline Baseline compact summary.
 * @param {Object} optimized Optimized compact summary.
 * @returns {ComparisonMetric[]} Comparable performance and reliability metrics.
 */
function compare(baseline, optimized) {
    const rows = [
        ['HTTP duration p95, ms', baseline.metrics.httpReqDuration.p95,
            optimized.metrics.httpReqDuration.p95, lowerIsBetter],
        ['HTTP duration average, ms', baseline.metrics.httpReqDuration.avg,
            optimized.metrics.httpReqDuration.avg, lowerIsBetter],
        ['HTTP waiting p95, ms', baseline.metrics.httpReqWaiting.p95,
            optimized.metrics.httpReqWaiting.p95, lowerIsBetter],
        ['Failed request rate', baseline.metrics.httpReqFailed.rate,
            optimized.metrics.httpReqFailed.rate, lowerIsBetter],
        ['Iteration rate, iter/s', baseline.metrics.iterations.rate,
            optimized.metrics.iterations.rate, higherIsBetter],
        ['Valid response rate', baseline.metrics.providerResponseValid.rate,
            optimized.metrics.providerResponseValid.rate, higherIsBetter],
        ['Dropped iterations', baseline.metrics.droppedIterations.count,
            optimized.metrics.droppedIterations.count, lowerIsBetter],
    ];

    return rows.map(([name, baselineValue, optimizedValue, calculator]) => ({
        name,
        baseline: baselineValue,
        optimized: optimizedValue,
        changePercent: calculator(baselineValue, optimizedValue),
    }));
}

/**
 * Builds CPU and memory comparison rows from resource-summary.json files.
 *
 * @param {Object} baseline Baseline resource summary.
 * @param {Object} optimized Optimized resource summary.
 * @returns {ComparisonMetric[]} Comparable operating-system process metrics.
 */
function compareResources(baseline, optimized) {
    const rows = [
        ['Process CPU average, %', baseline.process.cpuPercent.avg,
            optimized.process.cpuPercent.avg, lowerIsBetter],
        ['Process CPU p95, %', baseline.process.cpuPercent.p95,
            optimized.process.cpuPercent.p95, lowerIsBetter],
        ['Working set p95, bytes', baseline.process.workingSetBytes.p95,
            optimized.process.workingSetBytes.p95, lowerIsBetter],
        ['Working set max, bytes', baseline.process.workingSetBytes.max,
            optimized.process.workingSetBytes.max, lowerIsBetter],
        ['Private memory p95, bytes', baseline.process.privateMemoryBytes.p95,
            optimized.process.privateMemoryBytes.p95, lowerIsBetter],
        ['Thread count p95', baseline.process.threadCount.p95,
            optimized.process.threadCount.p95, lowerIsBetter],
    ];
    return rows.map(([name, baselineValue, optimizedValue, calculator]) => ({
        name,
        baseline: baselineValue,
        optimized: optimizedValue,
        changePercent: calculator(baselineValue, optimizedValue),
    }));
}

/**
 * Prints comparison rows using a consistent console-table shape.
 *
 * @param {ComparisonMetric[]} rows Metrics to print.
 * @returns {void}
 */
function printRows(rows) {
    console.table(rows.map((row) => ({
        Metric: row.name,
        Baseline: format(row.baseline),
        Optimized: format(row.optimized),
        'Improvement, %': format(row.changePercent),
    })));
}

/**
 * Loads command-line inputs and prints a baseline-versus-optimized comparison table.
 *
 * @returns {Promise<void>}
 */
async function main() {
    const [, , baselinePath, optimizedPath, baselineResourcePath, optimizedResourcePath] = process.argv;
    if (!baselinePath || !optimizedPath) {
        throw new Error('Usage: node compare-results.mjs <baseline-k6.json> <optimized-k6.json> ' +
            '[baseline-resource.json optimized-resource.json]');
    }
    if ((baselineResourcePath && !optimizedResourcePath) || (!baselineResourcePath && optimizedResourcePath)) {
        throw new Error('Both resource summary paths must be supplied together.');
    }

    const [baseline, optimized] = await Promise.all([
        loadSummary(baselinePath),
        loadSummary(optimizedPath),
    ]);
    if (baseline.profile !== optimized.profile) {
        throw new Error(`Profiles differ: '${baseline.profile}' and '${optimized.profile}'.`);
    }

    console.log(`Profile: ${baseline.profile}`);
    console.log(`Baseline: ${baseline.label} (${baseline.targetUrl})`);
    console.log(`Optimized: ${optimized.label} (${optimized.targetUrl})`);
    console.log('\nHTTP and k6 metrics');
    printRows(compare(baseline, optimized));

    if (baselineResourcePath && optimizedResourcePath) {
        const [baselineResources, optimizedResources] = await Promise.all([
            loadSummary(baselineResourcePath),
            loadSummary(optimizedResourcePath),
        ]);
        console.log('\nBackend CPU and memory metrics');
        printRows(compareResources(baselineResources, optimizedResources));
        console.log('\nDetailed GC and CLR series are available under runtimeCounters in each resource summary.');
    }
}

await main();
